# Build the predicted output: retain the three rectangular frames, clear exterior noise,
# and place the corresponding checkerboard color in each frame's strict interior.
R,C=22,26
g=[[0]*C for _ in range(R)]
frames=[(1,6,3,11,1,4),(10,13,2,5,2,8),(9,16,11,21,3,5)] # bounds inclusive, border color, interior fill
for r0,r1,c0,c1,border,fill in frames:
    for c in range(c0,c1+1):
        g[r0][c]=g[r1][c]=border
    for r in range(r0,r1+1):
        g[r][c0]=g[r][c1]=border
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            if (r+c)%2==0: g[r][c]=fill
assert len(g)==22 and all(len(row)==26 for row in g)
print('{"action":"submit","grid":'+__import__('json').dumps(g,separators=(',',':'))+'}')
